<style>.no-scrollbar::-webkit-scrollbar{display:none}.no-scrollbar{scrollbar-width:none}.no-scrollbar img{user-select:none;-webkit-user-drag:none}</style><script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.no-scrollbar').forEach(function(slider){const originals=[...slider.children];if(originals.length<2)return;originals.forEach(function(item){slider.appendChild(item.cloneNode(true))});let paused=false;function move(){if(!paused){slider.scrollLeft+=0.7;if(slider.scrollLeft>=slider.scrollWidth/2)slider.scrollLeft=0}requestAnimationFrame(move)}move();slider.addEventListener('mouseenter',()=>paused=true);slider.addEventListener('mouseleave',()=>paused=false);slider.addEventListener('touchstart',()=>paused=true,{passive:true});slider.addEventListener('touchend',()=>paused=false,{passive:true});let dragging=false,startX=0,startScroll=0;slider.addEventListener('pointerdown',e=>{dragging=true;paused=true;startX=e.clientX;startScroll=slider.scrollLeft;slider.setPointerCapture(e.pointerId)});slider.addEventListener('pointermove',e=>{if(dragging)slider.scrollLeft=startScroll-(e.clientX-startX)});slider.addEventListener('pointerup',()=>{dragging=false;paused=false});slider.addEventListener('pointercancel',()=>{dragging=false;paused=false})})});</script>
